func (q *Queries) EventosDeProspecto(ctx context.Context, prospectoID int64) ([]ComercialProspectoEvento, error) {
	rows, err := q.db.Query(ctx, eventosDeProspecto, prospectoID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ComercialProspectoEvento
	for rows.Next() {
		var i ComercialProspectoEvento
		if err := rows.Scan(
			&i.ID,
			&i.ProspectoID,
			&i.Tipo,
			&i.De,
			&i.A,
			&i.Motivo,
			&i.Datos,
			&i.ActorTipo,
			&i.ActorID,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

