const listarProspectos = `-- name: ListarProspectos :many
SELECT id, numero, empresa_id, origen, origen_detalle, nombre, documento, telefono, correo, direccion, lat, lon, zona_id, plan_interes_id, plan_interes_nombre, vendedor_id, estado, notas, motivo_perdida, perdido_en, ganado_en, obra_confirmada, alta_modo, alta_estado, cliente_argos_id, servicio_argos_id, orden_id, creado_por, idempotencia, version, created_at, updated_at, router_id, alta_error FROM comercial.prospectos p
WHERE ($1::bigint = 0 OR p.id < $1)
  AND ($2::boolean OR p.empresa_id IS NOT DISTINCT FROM $3::bigint)
  AND ($4::boolean OR p.zona_id = ANY ($5::bigint[]) OR p.vendedor_id = $6::bigint)
  AND (cardinality($7::text[]) = 0 OR p.estado = ANY ($7::text[]))
  AND ($8::text IS NULL OR p.origen = $8)
  AND ($9::bigint IS NULL OR p.vendedor_id = $9)
  AND (NOT $10::boolean OR p.vendedor_id IS NULL)
  AND ($11::bigint IS NULL OR p.zona_id = $11)
  AND (NOT $12::boolean OR p.lat IS NOT NULL)
  AND ($13::text IS NULL
       OR p.numero ILIKE '%' || $13 || '%'
       OR p.nombre ILIKE '%' || $13 || '%'
       OR p.telefono ILIKE '%' || $13 || '%'
       OR p.correo ILIKE '%' || $13 || '%'
       OR p.direccion ILIKE '%' || $13 || '%')
ORDER BY p.id DESC
LIMIT $14
`

type ListarProspectosParams struct {
	DespuesDe      int64
	Todas          bool
	EmpresaID      *int64
	Global         bool
	Zonas          []int64
	Propio         *int64
	Estados        []string
	Origen         *string
	VendedorID     *int64
	SinVendedor    bool
	ZonaID         *int64
	ConCoordenadas bool
	Q              *string
	Limite         int32
}

// Más recientes primero. @todas = sin filtro de empresa (actor sistema); si no, la empresa
// activa (null = modo sin conector). Alcance (falla cerrado): global, la zona del prospecto
// entre las del actor o el prospecto es del actor (vendedor).
func (q *Queries) ListarProspectos(ctx context.Context, arg ListarProspectosParams) ([]ComercialProspecto, error) {
	rows, err := q.db.Query(ctx, listarProspectos,
		arg.DespuesDe,
		arg.Todas,
		arg.EmpresaID,
		arg.Global,
		arg.Zonas,
		arg.Propio,
		arg.Estados,
		arg.Origen,
		arg.VendedorID,
		arg.SinVendedor,
		arg.ZonaID,
		arg.ConCoordenadas,
		arg.Q,
		arg.Limite,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ComercialProspecto
	for rows.Next() {
		var i ComercialProspecto
		if err := rows.Scan(
			&i.ID,
			&i.Numero,
			&i.EmpresaID,
			&i.Origen,
			&i.OrigenDetalle,
			&i.Nombre,
			&i.Documento,
			&i.Telefono,
			&i.Correo,
			&i.Direccion,
			&i.Lat,
			&i.Lon,
			&i.ZonaID,
			&i.PlanInteresID,
			&i.PlanInteresNombre,
			&i.VendedorID,
			&i.Estado,
			&i.Notas,
			&i.MotivoPerdida,
			&i.PerdidoEn,
			&i.GanadoEn,
			&i.ObraConfirmada,
			&i.AltaModo,
			&i.AltaEstado,
			&i.ClienteArgosID,
			&i.ServicioArgosID,
			&i.OrdenID,
			&i.CreadoPor,
			&i.Idempotencia,
			&i.Version,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RouterID,
			&i.AltaError,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

