func (q *Queries) UsuarioAsignable(ctx context.Context, id int64) (UsuarioAsignableRow, error) {
	row := q.db.QueryRow(ctx, usuarioAsignable, id)
	var i UsuarioAsignableRow
	err := row.Scan(
		&i.ID,
		&i.Nombre,
		&i.Tipo,
		&i.Activo,
	)
	return i, err
}
